    public DataTask update( DataTask entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a DataTask
	 * 
     * @param	id		UUID
     */
    public DataTask delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    DataTask entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Pipeline
     * 
     * @param	parentId	UUID
     * @param	assignment 	DataPipeline 
     * @return	DataTask
     */
    public DataTask assignPipeline( UUID parentId, DataPipeline assignment ) {
	    LOGGER.info("assigning Pipeline as " + assignment.toString() );

	    DataTask parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( DataPipeline.class, assignment.getDataPipelineId());

	    // ------------------------------------------
		// assign the Pipeline to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPipeline( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Pipeline
	 * 
	 * @param	parentId		UUID
	 * @return	DataTask
	 */
	public DataTask unAssignPipeline( UUID parentId ) {
		DataTask parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Pipeline on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Pipeline on the parent entithy
		// ------------------------------------------     
	    parentEntity.setPipeline(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the InputDatasets
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	DataTask
     */
    public DataTask addToInputDatasets( UUID parentId, DataSet addTo ) {
	    LOGGER.info("handling AssignInputDatasetsToDataTaskEvent - " );
	    
	    DataTask parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, addTo.getDataSetId());
	    
	    parentEntity.getInputDatasets().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the InputDatasets
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	DataTask
     */
	public DataTask removeFromInputDatasets( UUID parentId, DataSet removeFrom ) {
	    LOGGER.info("handling RemoveInputDatasetsFromDataTaskEvent " );
	
	    DataTask parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, removeFrom.getDataSetId());
	    
	    parentEntity.getInputDatasets().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

